function answerFrame(
  ws: WebSocket,
  session: ChatSession,
  validation: ValidationResult,
  sessionStore?: import('../../types/sessionStore.js').SessionStore
): void {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);
  if (message.type === 'list_sessions') {
    void handleListSessions(ws, session, message, sessionStore);
  }
}

async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  message: import('../../types/messages.js').ListSessionsMessage,
  sessionStore?: import('../../types/sessionStore.js').SessionStore
): Promise<void> {
  try {
    const sessions = (await sessionStore?.listFor?.(session.userId, {limit: message.limit, before: message.before})) ?? [];
    sendJson(ws, {
      type: 'session_list',
      sessions: sessions.map(s => ({
        ...s,
        createdAt: s.createdAt.toISOString(),
        updatedAt: s.updatedAt.toISOString(),
      })),
    });
  } catch (error) {
    log.error('ws', 'list sessions failed', {
      userId: session.userId,
      error: error instanceof Error ? error.message : String(error),
    });
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
  }
}

